            if (!parsedPhoneNumber.possible || !Str.isValidE164Phone(phoneNumber.slice(0))) {
                errors[INPUT_IDS.PHONE_NUMBER] = translate('bankAccount.error.phoneNumber');
            }
            return errors;
        },
        [translate],
    );

    return (
        <FormProvider
            formID={ONYXKEYS.FORMS.PERSONAL_DETAILS_FORM}
            submitButtonText={translate(isEditing ? 'common.confirm' : 'common.next')}
            onSubmit={handleSubmit}
            validate={validate}
            style={[styles.flexGrow1, styles.mt3]}
            submitButtonStyles={[styles.ph5, styles.mb0]}
            enabledWhenOffline
        >
            <View style={styles.ph5}>
                <Text style={[styles.textHeadlineLineHeightXXL, styles.mb3]}>{translate('privatePersonalDetails.enterPhoneNumber')}</Text>
                <InputWrapper
                    InputComponent={TextInput}
                    inputID={INPUT_IDS.PHONE_NUMBER}
                    label={translate('common.phoneNumber')}
                    aria-label={translate('common.phoneNumber')}
                    role={CONST.ROLE.PRESENTATION}
                    inputMode={CONST.INPUT_MODE.TEL}
                    defaultValue={personalDetailsValues[INPUT_IDS.PHONE_NUMBER]}
                />
            </View>
        </FormProvider>
    );
}

function AddressStep({isEditing, onNext, personalDetailsValues}: CustomSubStepProps) {
    const {translate} = useLocalize();
    const styles = useThemeStyles();

    const [currentCountry, setCurrentCountry] = useState(personalDetailsValues[INPUT_IDS.COUNTRY]);
    const [state, setState] = useState(personalDetailsValues[INPUT_IDS.STATE]);
    const [city, setCity] = useState(personalDetailsValues[INPUT_IDS.CITY]);
    const [zipcode, setZipcode] = useState(personalDetailsValues[INPUT_IDS.ZIP_POST_CODE]);

    const handleSubmit = usePersonalDetailsFormSubmit({
        fieldIds: STEP_FIELDS,
        onNext,
        shouldSaveDraft: true,
    });

    const handleAddressChange = useCallback((value: unknown, key: unknown) => {
        const addressPart = value as string;
        const addressPartKey = key as keyof Address;

        if (addressPartKey !== INPUT_IDS.COUNTRY && addressPartKey !== INPUT_IDS.STATE && addressPartKey !== INPUT_IDS.CITY && addressPartKey !== INPUT_IDS.ZIP_POST_CODE) {
            return;
        }
        if (addressPartKey === INPUT_IDS.COUNTRY) {
            setCurrentCountry(addressPart as Country | '');
            setState('');
            setCity('');
            setZipcode('');
            return;
        }
        if (addressPartKey === INPUT_IDS.STATE) {
            setState(addressPart);
            setCity('');
            setZipcode('');
            return;
        }
        if (addressPartKey === INPUT_IDS.CITY) {
            setCity(addressPart);
            setZipcode('');
            return;
        }
        setZipcode(addressPart);
    }, []);

    const isUSAForm = currentCountry === CONST.COUNTRY.US;

    const zipSampleFormat = (currentCountry && (CONST.COUNTRY_ZIP_REGEX_DATA[currentCountry] as CountryZipRegex)?.samples) ?? '';

    const zipFormat = translate('common.zipCodeExampleFormat', {zipSampleFormat});

    const validate = useCallback(
        (values: FormOnyxValues<typeof ONYXKEYS.FORMS.PERSONAL_DETAILS_FORM>): FormInputErrors<typeof ONYXKEYS.FORMS.PERSONAL_DETAILS_FORM> => {
            const errors: FormInputErrors<typeof ONYXKEYS.FORMS.PERSONAL_DETAILS_FORM> = {};
            const addressRequiredFields = [INPUT_IDS.ADDRESS_LINE_1, INPUT_IDS.CITY, INPUT_IDS.COUNTRY, INPUT_IDS.STATE] as const;
            addressRequiredFields.forEach((fieldKey) => {
                const fieldValue = values[fieldKey] ?? '';
                if (ValidationUtils.isRequiredFulfilled(fieldValue)) {
                    return;
                }
                errors[fieldKey] = translate('common.error.fieldRequired');
            });

            // If no country is selected, default value is an empty string and there's no related regex data so we default to an empty object
            const countryRegexDetails = (values.country ? CONST.COUNTRY_ZIP_REGEX_DATA?.[values.country] : {}) as CountryZipRegex;

            // The postal code system might not exist for a country, so no regex either for them.
            const countrySpecificZipRegex = countryRegexDetails?.regex;
            const countryZipFormat = countryRegexDetails?.samples ?? '';
            if (countrySpecificZipRegex) {
                if (!countrySpecificZipRegex.test(values[INPUT_IDS.ZIP_POST_CODE]?.trim().toUpperCase())) {
                    if (ValidationUtils.isRequiredFulfilled(values[INPUT_IDS.ZIP_POST_CODE]?.trim())) {
                        errors[INPUT_IDS.ZIP_POST_CODE] = translate('privatePersonalDetails.error.incorrectZipFormat', {zipFormat: countryZipFormat});
                    } else {
                        errors[INPUT_IDS.ZIP_POST_CODE] = translate('common.error.fieldRequired');
                    }
                }
            } else if (!CONST.GENERIC_ZIP_CODE_REGEX.test(values[INPUT_IDS.ZIP_POST_CODE]?.trim()?.toUpperCase() ?? '')) {
                errors[INPUT_IDS.ZIP_POST_CODE] = translate('privatePersonalDetails.error.incorrectZipFormat');
            }
            return errors;
        },
        [translate],
    );

    return (
        <FormProvider
            formID={ONYXKEYS.FORMS.PERSONAL_DETAILS_FORM}
            submitButtonText={translate(isEditing ? 'common.confirm' : 'common.next')}
            onSubmit={handleSubmit}
            validate={validate}
            style={[styles.flexGrow1, styles.mt3]}
            submitButtonStyles={[styles.ph5, styles.mb0]}
            enabledWhenOffline
        >
            <View style={styles.ph5}>
                <Text style={[styles.textHeadlineLineHeightXXL, styles.mb3]}>{translate('privatePersonalDetails.enterAddress')}</Text>
                <View>
                    <InputWrapper
                        InputComponent={AddressSearch}
                        inputID={INPUT_IDS.ADDRESS_LINE_1}
                        label={translate('common.addressLine', {lineNumber: 1})}
                        onValueChange={(data: unknown, key: unknown) => {
                            handleAddressChange(data, key);
                        }}
                        defaultValue={personalDetailsValues[INPUT_IDS.ADDRESS_LINE_1]}
                        renamedInputKeys={{
                            street: INPUT_IDS.ADDRESS_LINE_1,
                            street2: INPUT_IDS.ADDRESS_LINE_2,
                            city: INPUT_IDS.CITY,
                            state: INPUT_IDS.STATE,
                            zipCode: INPUT_IDS.ZIP_POST_CODE,
                            country: INPUT_IDS.COUNTRY as Country,
                        }}
                        maxInputLength={CONST.FORM_CHARACTER_LIMIT}
                    />
                </View>
                <InputWrapper
                    InputComponent={TextInput}
                    inputID={INPUT_IDS.ADDRESS_LINE_2}
                    label={translate('common.addressLine', {lineNumber: 2})}
                    aria-label={translate('common.addressLine', {lineNumber: 2})}
                    role={CONST.ROLE.PRESENTATION}
                    defaultValue={personalDetailsValues[INPUT_IDS.ADDRESS_LINE_2]}
                    maxLength={CONST.FORM_CHARACTER_LIMIT}
                    spellCheck={false}
                    containerStyles={styles.mt5}
                />
                <View style={[styles.mt2, styles.mhn5]}>
                    <InputWrapper
                        InputComponent={CountryPicker}
                        inputID={INPUT_IDS.COUNTRY}
                        value={currentCountry}
                        onValueChange={handleAddressChange}
                    />
                </View>
                {isUSAForm ? (
                    <View style={[styles.mt2, styles.mhn5]}>
                        <InputWrapper
                            InputComponent={StatePicker}
                            inputID={INPUT_IDS.STATE}
                            value={state as State}
                            onValueChange={handleAddressChange}
                        />
                    </View>
                ) : (
                    <InputWrapper
                        InputComponent={TextInput}
                        inputID={INPUT_IDS.STATE}
                        label={translate('common.stateOrProvince')}
                        aria-label={translate('common.stateOrProvince')}
                        role={CONST.ROLE.PRESENTATION}
                        value={state}
                        maxLength={CONST.STATE_CHARACTER_LIMIT}
                        spellCheck={false}
                        onValueChange={handleAddressChange}
                        containerStyles={styles.mt2}
                    />
                )}
                <InputWrapper
                    InputComponent={TextInput}
                    inputID={INPUT_IDS.CITY}
                    label={translate('common.city')}
                    aria-label={translate('common.city')}
                    role={CONST.ROLE.PRESENTATION}
                    defaultValue={city}
                    maxLength={CONST.FORM_CHARACTER_LIMIT}
                    spellCheck={false}
                    onValueChange={handleAddressChange}
                    containerStyles={isUSAForm ? styles.mt2 : styles.mt5}
                />
                <InputWrapper
                    InputComponent={TextInput}
                    inputID={INPUT_IDS.ZIP_POST_CODE}
                    label={translate('common.zipPostCode')}
                    aria-label={translate('common.zipPostCode')}
                    role={CONST.ROLE.PRESENTATION}
                    autoCapitalize="characters"
                    defaultValue={zipcode}
                    maxLength={CONST.BANK_ACCOUNT.MAX_LENGTH.ZIP_CODE}
                    hint={zipFormat}
                    onValueChange={handleAddressChange}
                    containerStyles={styles.mt5}
                />
            </View>
        </FormProvider>
    );
}

function DebugDetails({data, children, onSave, onDelete, validate}: DebugDetailsProps) {
    const {translate} = useLocalize();
    const styles = useThemeStyles();
    const [formDraftData] = useOnyx(ONYXKEYS.FORMS.DEBUG_DETAILS_FORM_DRAFT);
    const booleanFields = useMemo(
        () =>
            Object.entries(data ?? {})
                .filter(([, value]) => typeof value === 'boolean')
                .sort((a, b) => a[0].localeCompare(b[0])) as Array<[string, boolean]>,
        [data],
    );
    const constantFields = useMemo(
        () =>
            Object.entries(data ?? {})
                .filter((entry): entry is [string, string] => DETAILS_CONSTANT_FIELDS.includes(entry[0] as DetailsConstantFieldsKeys))
                .sort((a, b) => a[0].localeCompare(b[0])),
        [data],
    );
    const numberFields = useMemo(
        () =>
            Object.entries(data ?? {})
                .filter((entry): entry is [string, number] => typeof entry[1] === 'number')
                .sort((a, b) => a[0].localeCompare(b[0])),
        [data],
    );
    const textFields = useMemo(
        () =>
            Object.entries(data ?? {})
                .filter(
                    (entry): entry is [string, string | ObjectType] =>
                        (typeof entry[1] === 'string' || typeof entry[1] === 'object') &&
                        !DETAILS_CONSTANT_FIELDS.includes(entry[0] as DetailsConstantFieldsKeys) &&
                        !DETAILS_DATETIME_FIELDS.includes(entry[0] as DetailsDatetimeFieldsKeys),
                )
                .map(([key, value]) => [key, DebugUtils.onyxDataToString(value)])
                .sort((a, b) => (a.at(0) ?? '').localeCompare(b.at(0) ?? '')),
        [data],
    );
    const dateTimeFields = useMemo(
        () => Object.entries(data ?? {}).filter((entry): entry is [string, string] => DETAILS_DATETIME_FIELDS.includes(entry[0] as DetailsDatetimeFieldsKeys)),
        [data],
    );

    const validator = useCallback(
        (values: FormOnyxValues<typeof ONYXKEYS.FORMS.DEBUG_DETAILS_FORM>): FormInputErrors<typeof ONYXKEYS.FORMS.DEBUG_DETAILS_FORM> => {
            const newErrors: Record<string, string | undefined> = {};
            Object.entries(values).forEach(([key, value]) => {
                try {
                    validate(key, DebugUtils.onyxDataToString(value));
                } catch (e) {
                    const {cause, message} = e as SyntaxError;
                    newErrors[key] = cause || message === 'debug.missingValue' ? translate(message as TranslationPaths, cause as never) : message;
                }
            });
            return newErrors;
        },
        [translate, validate],
    );

    useEffect(() => {
        Debug.resetDebugDetailsDraftForm();
    }, []);

    const handleSubmit = useCallback(
        (values: FormOnyxValues<typeof ONYXKEYS.FORMS.DEBUG_DETAILS_FORM>) => {
            const dataPreparedToSave = Object.entries<string | boolean>(values).reduce((acc: Record<string, unknown>, [key, value]) => {
                if (typeof value === 'boolean') {
                    acc[key] = value;
                } else {
                    acc[key] = DebugUtils.stringToOnyxData(value, typeof data?.[key as keyof typeof data] as OnyxDataType);
                }
                return acc;
            }, {});

            onSave(dataPreparedToSave);
        },
        [data, onSave],
    );

    const isSubmitDisabled = useMemo(
        () =>
            !Object.entries(formDraftData ?? {}).some(([key, value]) => {
                const onyxData = data?.[key as keyof typeof data];
                if (typeof value === 'string') {
                    return !DebugUtils.compareStringWithOnyxData(value, onyxData);
                }
                return onyxData !== value;
            }),
        [formDraftData, data],
    );

    return (
        <ScrollView style={styles.mv5}>
            {children}
            <FormProvider
                style={styles.flexGrow1}
                formID={ONYXKEYS.FORMS.DEBUG_DETAILS_FORM}
                validate={validator}
                shouldValidateOnChange
                onSubmit={handleSubmit}
                isSubmitDisabled={isSubmitDisabled}
                submitButtonText={translate('common.save')}
                submitButtonStyles={[styles.ph5, styles.mt0]}
                enabledWhenOffline
                allowHTML
            >
                <Text style={[styles.headerText, styles.ph5, styles.mb3]}>{translate('debug.textFields')}</Text>
                <View style={[styles.mb5, styles.ph5, styles.gap5]}>
                    {textFields.map(([key, value]) => {
                        const numberOfLines = DebugUtils.getNumberOfLinesFromString((formDraftData?.[key as keyof typeof formDraftData] as string) ?? value);
                        return (
                            <InputWrapper
                                InputComponent={TextInput}
                                inputID={key}
                                accessibilityLabel={key}
                                shouldSaveDraft
                                forceActiveLabel
                                label={key}
                                numberOfLines={numberOfLines}
                                multiline={numberOfLines > 1}
                                defaultValue={value}
                                disabled={DETAILS_DISABLED_KEYS.includes(key as DetailsDisabledKeys)}
                                shouldInterceptSwipe
                            />
                        );
                    })}
                    {textFields.length === 0 && <Text style={[styles.textNormalThemeText, styles.ph5]}>{translate('debug.none')}</Text>}
                </View>
                <Text style={[styles.headerText, styles.ph5, styles.mb3]}>{translate('debug.numberFields')}</Text>
                <View style={[styles.mb5, styles.ph5, styles.gap5]}>
                    {numberFields.map(([key, value]) => (
                        <InputWrapper
                            InputComponent={TextInput}
                            inputID={key}
                            accessibilityLabel={key}
                            shouldSaveDraft
                            forceActiveLabel
                            label={key}
                            defaultValue={String(value)}
                            disabled={DETAILS_DISABLED_KEYS.includes(key as DetailsDisabledKeys)}
                            shouldInterceptSwipe
                        />
                    ))}
                    {numberFields.length === 0 && <Text style={[styles.textNormalThemeText, styles.ph5]}>{translate('debug.none')}</Text>}
                </View>
                <Text style={[styles.headerText, styles.ph5, styles.mb3]}>{translate('debug.constantFields')}</Text>
                <View style={styles.mb5}>
                    {constantFields.map(([key, value]) => (
                        <InputWrapper
                            key={key}
                            InputComponent={ConstantSelector}
                            inputID={key}
                            name={key}
                            shouldSaveDraft
                            defaultValue={String(value)}
                        />
                    ))}
                    {constantFields.length === 0 && <Text style={[styles.textNormalThemeText, styles.ph5]}>{translate('debug.none')}</Text>}
                </View>
                <Text style={[styles.headerText, styles.ph5, styles.mb3]}>{translate('debug.dateTimeFields')}</Text>
                <View style={styles.mb5}>
                    {dateTimeFields.map(([key, value]) => (
                        <InputWrapper
                            key={key}
                            InputComponent={DateTimeSelector}
                            inputID={key}
                            name={key}
                            shouldSaveDraft
                            defaultValue={String(value)}
                        />
                    ))}
                    {dateTimeFields.length === 0 && <Text style={[styles.textNormalThemeText, styles.ph5]}>{translate('debug.none')}</Text>}
                </View>
                <Text style={[styles.headerText, styles.ph5, styles.mb3]}>{translate('debug.booleanFields')}</Text>
                <View style={[styles.mb5, styles.ph5, styles.gap5]}>
                    {booleanFields.map(([key, value]) => (
                        <InputWrapper
                            InputComponent={CheckboxWithLabel}
                            label={key}
                            inputID={key}
                            shouldSaveDraft
                            accessibilityLabel={key}
                            defaultValue={value}
                        />
                    ))}
                    {booleanFields.length === 0 && <Text style={[styles.textNormalThemeText, styles.ph5]}>{translate('debug.none')}</Text>}
                </View>
                <Text style={[styles.headerText, styles.textAlignCenter]}>{translate('debug.hint')}</Text>
                <View style={[styles.ph5, styles.mb3, styles.mt5]}>
                    <Button
                        danger
                        large
                        text={translate('common.delete')}
                        onPress={() => {
                            onDelete();
                            Navigation.goBack();
                        }}
                    />
                </View>
            </FormProvider>
        </ScrollView>
    );
}

